import{_ as e,a,b as r}from"./chunks/console-models.1j_Niwy1.js";import{_ as n}from"./chunks/console-usage.mPwN76Mj.js";import{_ as o,o as i,c as d,a0 as l}from"./chunks/framework.B7o6dWmz.js";const A=JSON.parse('{"title":"NetonAPI 1.0.0：从运营平台出发设计的 AI API 中转站","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/releases/1.0.0.md","filePath":"zh-Hans/releases/1.0.0.md","lastUpdated":1794047970000}'),s={name:"zh-Hans/releases/1.0.0.md"};function h(p,t,g,c,m,u){return i(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="netonapi-1-0-0-从运营平台出发设计的-ai-api-中转站" tabindex="-1">NetonAPI 1.0.0：从运营平台出发设计的 AI API 中转站 <a class="header-anchor" href="#netonapi-1-0-0-从运营平台出发设计的-ai-api-中转站" aria-label="Permalink to &quot;NetonAPI 1.0.0：从运营平台出发设计的 AI API 中转站&quot;">​</a></h1><p>2026-11-07</p><p>NetonAPI 是一个自托管的大模型 API 中转网关：一个 Key 调用 OpenAI、Claude、Gemini、DeepSeek、Qwen、GLM、Kimi、Grok 等主流模型， 按 token 计费，自带运营后台与用户控制台。今天发布 1.0.0 正式版。</p><h2 id="为什么再做一个中转站" tabindex="-1">为什么再做一个中转站 <a class="header-anchor" href="#为什么再做一个中转站" aria-label="Permalink to &quot;为什么再做一个中转站&quot;">​</a></h2><p>现有的开源中转站大多从「把请求转出去」出发，计费是在转发上叠加的倍率。真正运营一个中转站，难的是另外几件事： <strong>每个模型卖多少钱、拿货多少钱、这一单赚没赚钱、给大客户的折扣会不会卖亏、用户看到的价格和账单对不对得上。</strong> NetonAPI 从第一行代码起就围绕这些问题设计。</p><h3 id="_1-以官方价为锚定价" tabindex="-1">1. 以官方价为锚定价 <a class="header-anchor" href="#_1-以官方价为锚定价" aria-label="Permalink to &quot;1. 以官方价为锚定价&quot;">​</a></h3><p>客户比价的锚点是官方价（「Claude 官方 $3，这里 7 折」）。NetonAPI 的售价直接写成「官方价 × 加价率」， 给一组用户或单个大客户的优惠写成「官方价 N 折」——官方价调整时自动跟随，承诺一直成立。 不需要去换算一层层倍率。</p><h3 id="_2-每条渠道都有真实成本-亏本的价格保存不了" tabindex="-1">2. 每条渠道都有真实成本，亏本的价格保存不了 <a class="header-anchor" href="#_2-每条渠道都有真实成本-亏本的价格保存不了" aria-label="Permalink to &quot;2. 每条渠道都有真实成本，亏本的价格保存不了&quot;">​</a></h3><p>每条上游渠道记录自己的拿货价：官方价折扣、自动拉取上游中转站的价目接口、或按模型手填；成本异常变动先挂起，等运营确认。 任何定价（全站价、分组价、给单个用户的协议价）保存前都按<strong>真实会走的每条渠道</strong>核算毛利，<strong>低于成本直接拒绝</strong>。 定价体检列出每个「分组 × 渠道」组合的最差毛利，利润看板按分组、渠道统计收入、成本与亏损。</p><h3 id="_3-展示的单价就是扣费的单价" tabindex="-1">3. 展示的单价就是扣费的单价 <a class="header-anchor" href="#_3-展示的单价就是扣费的单价" aria-label="Permalink to &quot;3. 展示的单价就是扣费的单价&quot;">​</a></h3><p>扣费 = tokens × 用户在控制台看到的单价，逐项向上取整；价格页、控制台、账单三处是同一个数，客户可以逐笔对账。 上游用量数据不规范（缓存数比输入还多、缓存价缺失等）时按保守口径计，不少收、不白送。</p><h3 id="_4-钱的账是两阶段的" tabindex="-1">4. 钱的账是两阶段的 <a class="header-anchor" href="#_4-钱的账是两阶段的" aria-label="Permalink to &quot;4. 钱的账是两阶段的&quot;">​</a></h3><p>每次请求先按上界预留额度，结束后按实际用量结算，定价快照随请求冻结——中途改价不影响在途请求。 进程崩溃后自动恢复，说不清的账进人工复核队列，<strong>不会自动退款也不会重复扣费</strong>。</p><h3 id="_5-给运营用的后台" tabindex="-1">5. 给运营用的后台 <a class="header-anchor" href="#_5-给运营用的后台" aria-label="Permalink to &quot;5. 给运营用的后台&quot;">​</a></h3><ul><li><strong>协议定价</strong>：搜一个用户，逐模型（或批量）设「官方价 N 折」，实时显示他的价格和毛利。</li><li><strong>计费分组由 API Key 决定</strong>：专线、特价直接指定到某把 Key，开了就生效。</li><li><strong>菜单与按钮级权限</strong>，预置网关运营、财务、客服、只读四个角色，建账号勾一个角色就能用。</li><li><strong>API Key 只在创建时显示一次</strong>，库里只存哈希；上游渠道 Key 加密存储，支付密钥只写不读。</li></ul><h2 id="看一眼" tabindex="-1">看一眼 <a class="header-anchor" href="#看一眼" aria-label="Permalink to &quot;看一眼&quot;">​</a></h2><table tabindex="0"><thead><tr><th>运营概览：收入、成本、毛利</th><th>协议定价：给大客户逐模型打折，实时显示毛利</th></tr></thead><tbody><tr><td><img src="'+e+'" alt="网关概览"></td><td><img src="'+a+'" alt="协议定价"></td></tr><tr><td><strong>用户控制台：模型与价格</strong></td><td><strong>用户控制台：用量与额度</strong></td></tr><tr><td><img src="'+r+'" alt="模型与价格"></td><td><img src="'+n+'" alt="用量与额度"></td></tr></tbody></table><h2 id="_1-0-0-包含什么" tabindex="-1">1.0.0 包含什么 <a class="header-anchor" href="#_1-0-0-包含什么" aria-label="Permalink to &quot;1.0.0 包含什么&quot;">​</a></h2><ul><li><strong>接入</strong>：OpenAI（Chat Completions、Responses、Embeddings、Images、Audio、Rerank）、Anthropic Messages、Gemini 原生接口， 入站与上游协议<strong>任意方向互转</strong>（工具调用、图片、thinking、缓存用量保真），流式与非流式全覆盖；Claude Code、各家官方 SDK 直接可用。</li><li><strong>上游</strong>：OpenAI 兼容站（含各类中转站）、Azure OpenAI、Anthropic、Gemini、AWS Bedrock、Vertex AI。</li><li><strong>路由与容错</strong>：优先级 + 权重，失败自动换渠道（上游报「没有这个模型」也会换），Key 自动停用与冷却，定时测速，长回答不截断。</li><li><strong>计费</strong>：按 token、按次、按长上下文分档；缓存读写分别计价；全站价、分组价、协议价三层，逐笔对账。</li><li><strong>钱</strong>：管理员手动充值、兑换码、在线支付（支付宝、四方支付，可扩展），完整余额流水。</li><li><strong>运营</strong>：概览（收入 / 成本 / 毛利、每日趋势、模型与用户排行、渠道健康）、价源同步与校准、调价记录、用量日志、结算复核、 Prometheus 指标。</li><li><strong>用户</strong>：注册登录（账号密码、手机验证码）、API Key 自助管理（预算、有效期、模型范围、IP 白名单）、用量与账单、模型价格表、接入说明。</li><li><strong>部署</strong>：Kotlin/Native 编译的<strong>单个原生可执行文件</strong>，运行期无 JVM；依赖 PostgreSQL（Redis 可选）。 框架（Neton 1.1.0）、neton-ai 0.1.0、geolite4k 0.1.2 直接从 Maven Central 下载，只凭公开源码即可构建。</li></ul><h2 id="与主流开源中转站对照" tabindex="-1">与主流开源中转站对照 <a class="header-anchor" href="#与主流开源中转站对照" aria-label="Permalink to &quot;与主流开源中转站对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>NetonAPI 1.0</th><th>new-api</th><th>one-api</th></tr></thead><tbody><tr><td>定价方式</td><td>官方价为锚，「官方价 N 折」</td><td>模型 × 补全 × 分组倍率</td><td>分组 × 模型 × 补全倍率</td></tr><tr><td>按用户 × 模型的协议价</td><td>有</td><td>按用户分组倍率</td><td>按用户分组倍率</td></tr><tr><td>渠道真实成本 / 毛利保护</td><td>有，低于成本保存不了</td><td>公开文档未涉及</td><td>公开文档未涉及</td></tr><tr><td>展示单价 = 扣费单价</td><td>是，逐笔可对账</td><td>预扣后多退少补</td><td>预扣后结算</td></tr><tr><td>账务</td><td>两阶段预留 → 结算，崩溃可恢复</td><td>预扣 + 后结算</td><td>预扣 + 后结算</td></tr><tr><td>API Key</td><td>只显示一次，只存哈希</td><td>可随时查看</td><td>可随时查看</td></tr><tr><td>协议互转</td><td>OpenAI / Anthropic / Gemini 任意方向</td><td>四种文本协议互转</td><td>统一为 OpenAI</td></tr><tr><td>上游类型</td><td>6 类（含所有 OpenAI 兼容站）</td><td>数十种</td><td>30 余家</td></tr><tr><td>任务类接口（MJ、视频）</td><td>暂不支持</td><td>支持</td><td>不支持</td></tr><tr><td>部署</td><td>单个原生可执行文件，PostgreSQL</td><td>Go / Docker，多种数据库</td><td>Go / Docker，SQLite / MySQL</td></tr></tbody></table><p>完整对比见 <a href="/zh-Hans/compare">对比页</a>。new-api、one-api 两列依据其公开文档整理（2026-11）。</p><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><p>刻意写出来：</p><ul><li>不支持 Midjourney、Suno、视频生成等任务类接口；上游类型少于 new-api（但所有 OpenAI 兼容站都能接）。</li><li>用户侧暂无第三方登录（GitHub、OIDC 等）与两步验证。</li><li>只支持 PostgreSQL。</li><li>Docker / compose 部署路径尚未在真实 Docker 宿主上跑过；推荐按 DEPLOY.md 的裸机方式部署。</li></ul><h2 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to &quot;仓库&quot;">​</a></h2><ul><li>服务端：<a href="https://github.com/netonapi/netonapi" target="_blank" rel="noreferrer">netonapi/netonapi</a></li><li>管理后台：<a href="https://github.com/netonapi/netonapi-admincp" target="_blank" rel="noreferrer">netonapi/netonapi-admincp</a></li><li>网站前端（门户、价格页、用户控制台）：<a href="https://github.com/netonapi/netonapi-web" target="_blank" rel="noreferrer">netonapi/netonapi-web</a></li><li>部署说明与端到端测试：<a href="https://github.com/zoujiaqing/nanogate/blob/main/DEPLOY.md" target="_blank" rel="noreferrer">DEPLOY.md</a></li></ul><p>许可：Apache-2.0。</p>',28)])])}const I=o(s,[["render",h]]);export{A as __pageData,I as default};
